#!/bin/bash
# cold (fresh RVT_CORE_CACHE) cProfile of the viewer conversion of studyx studyx-008 on remote-host (geometry stage 1109 s); top cumulative/tottime in ~/offload/prof_studyx_008.txt there
cd ~/src/rvt-viewer
~/.local/share/offload/h2run run profstudyx --env occ --dir ~/src/rvt-viewer -- bash -c "rm -rf ~/.cache/rvt-viewer/prof-work ~/offload/profcache; RVT_CORE_CACHE=~/offload/profcache RVT_CAPPED=1 python -c \"import cProfile,pstats,sys; sys.path.insert(0,'.'); from rvtviewer.cli import main; cProfile.run('main([\\\"convert\\\",\\\"~/scratch-famtest/studyx/studyx-008.rvt\\\",\\\"~/.cache/rvt-viewer/prof-work\\\"])','~/offload/prof_studyx_008.pstats')\"; python -c \"import pstats; p=pstats.Stats('~/offload/prof_studyx_008.pstats'); p.sort_stats('tottime').print_stats(25)\" > ~/offload/prof_studyx_008.txt" 2>&1 | tail -2
